<?php if(!defined('RUBIZH_AUTH')){http_response_code(404);exit;}
$q=shopStoreDatabase()->prepare("SELECT d.*,o.order_number,c.contact_json FROM rubizh_order_donations d JOIN rubizh_customer_orders o ON o.id=d.order_id LEFT JOIN rubizh_order_details c ON c.order_id=o.id JOIN rubizh_account_orders a ON a.order_id=o.id WHERE a.customer_id=? AND o.payment_status='paid' AND o.status NOT IN ('cancelled','returned') ORDER BY d.paid_at DESC");$q->execute([customerId()]);$donations=$q->fetchAll(PDO::FETCH_ASSOC);$sum=(int)array_sum(array_column($donations,'amount'));?>
<div class="account-card"><h2>Внесок на ЗСУ</h2><p>Ваші внески за весь час: <strong class="order-large-sum"><?=$sum?> ₴</strong></p><p>3% від оплаченої вартості товарів на бригаду, обрану під час оформлення.</p><?php if(!$donations):?><div class="empty-state"><h3>Внесків поки немає</h3><p>Після оплати замовлення внесок зʼявиться тут.</p></div><?php endif;?><?php foreach($donations as $d):$contact=json_decode($d['contact_json']??'{}',true);?><div class="donation-order"><a href="/auth/?tab=orders&amp;order=<?=(int)$d['order_id']?>"><?=esc($d['order_number'])?></a><strong><?=(int)$d['amount']?> ₴</strong><p><?=esc(shopDonationBrigade(is_array($contact)?$contact:[]))?></p><?php if($d['batch_id']):?><p>Ваш внесок <?=(int)$d['amount']?> ₴ — у цьому переказі разом із внесками інших покупців РУБІЖ.</p><a href="/shop/donation-proof.php?order=<?=(int)$d['order_id']?>" target="_blank" rel="noopener">Переглянути скрін переказу →</a><?php else:?><p>Скрін надішлемо до <?=esc(customerDate($d['due_at']))?>.</p><?php endif;?></div><?php endforeach;?></div>
